// WF-04 | Stage 2 - Validation
const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
  const r = (Math.random() * 16) | 0;
  return (c === 'x' ? r : (r & 0x3) | 0x8).toString(16);
});

const inputPrompt = (typeof body.input === 'string' ? body.input.trim() : '');
const context = body.context || {};
const reqOrgId = (typeof body.organization_id === 'string' ? body.organization_id.trim() : '');
const orgId = UUID_RE.test(reqOrgId) ? reqOrgId : '11111111-1111-4111-8111-111111111111';

const rawCorr = headers['x-correlation-id'] || body.correlation_id || '';
const correlationId = UUID_RE.test(rawCorr) ? rawCorr : uuid();

const apiKey = headers['x-api-key'] || headers['authorization'] || '';
const expectedKey = 'change-this-core-api-key';
const apiKeyValid = Boolean(apiKey && (apiKey === expectedKey || apiKey === `Bearer ${expectedKey}`));

const errors = [];
if (!inputPrompt) {
  errors.push({ field: 'input', message: 'Input prompt không được để trống.' });
}
if (!apiKeyValid) {
  errors.push({ field: 'auth', message: 'X-API-Key không hợp lệ hoặc thiếu.' });
}

return [{
  json: {
    valid: errors.length === 0,
    apiKeyValid,
    errors,
    input: inputPrompt,
    context,
    organization_id: orgId,
    correlation_id: correlationId,
    received_at: new Date().toISOString()
  }
}];

// WF-04 | Stage 4 - Data Processing & Tool Policy Injection
const item = $input.first().json;
const toolPolicy = [
  {
    tool: 'exchange_rate',
    description: 'Retrieve current FX / currency exchange rate',
    params: { from: 'Currency code (e.g. USD, EUR, VND)', to: 'Target currency code (e.g. EUR, VND, JPY)' }
  },
  {
    tool: 'weather',
    description: 'Retrieve current weather forecast by coordinates',
    params: { latitude: 'number between -90 and 90', longitude: 'number between -180 and 180' }
  },
  {
    tool: 'no_action',
    description: 'Sufficient context already available or no external tool needed',
    params: {}
  }
];

return [{
  json: {
    ...item,
    toolPolicy,
    runInput: {
      input: item.input,
      context: item.context,
      correlation_id: item.correlation_id,
      timestamp: item.received_at
    }
  }
}];

