// WF-04 | Stage 6 - AI Agent Planner
const prev = $('04 Data Processing').first().json;
const runRecord = $input.first().json;
const workflowRunId = runRecord.id;

const prompt = String(prev.input || '').toLowerCase();
const ctx = prev.context || {};

let action = 'no_action';
let toolArgs = {};
let reason = 'Context is sufficient or prompt does not require external data.';
let confidence = 0.95;

const fxKeywords = /tỷ giá|tiền tệ|đổi tiền|quy đổi|ngoại tệ|exchange rate|currency|usd|eur|vnd|jpy|gbp/;
const weatherKeywords = /thời tiết|nhiệt độ|trời mưa|trời nắng|dự báo thời tiết|weather|temperature|forecast/;

if (fxKeywords.test(prompt) || ctx.need_exchange_rate) {
  action = 'exchange_rate';
  let from = 'USD';
  let to = 'EUR';

  if (/eur|euro/i.test(prompt)) to = 'EUR';
  if (/vnd|đồng/i.test(prompt)) to = 'VND';
  if (/jpy|yên/i.test(prompt)) to = 'JPY';
  if (/gbp|bảng/i.test(prompt)) to = 'GBP';

  if (/từ eur|from eur/i.test(prompt)) from = 'EUR';
  if (/từ vnd|from vnd/i.test(prompt)) from = 'VND';

  toolArgs = { from, to };
  reason = `The user request requires current exchange rate data from ${from} to ${to}.`;
  confidence = 0.94;
} else if (weatherKeywords.test(prompt) || ctx.need_weather) {
  action = 'weather';
  let lat = 16.0544;
  let lon = 108.2022;
  let city = 'Đà Nẵng';

  if (/hà nội|hanoi/i.test(prompt)) { lat = 21.0285; lon = 105.8542; city = 'Hà Nội'; }
  else if (/hồ chí minh|sài gòn|hcmc|saigon/i.test(prompt)) { lat = 10.8231; lon = 106.6297; city = 'TP. Hồ Chí Minh'; }

  toolArgs = { latitude: lat, longitude: lon, location: city };
  reason = `The user request requires real-time weather information for ${city}.`;
  confidence = 0.96;
} else {
  action = 'no_action';
  toolArgs = {};
  reason = 'The provided context is sufficient to answer without external tool invocation.';
  confidence = 0.98;
}

return [{
  json: {
    workflow_run_id: workflowRunId,
    correlation_id: prev.correlation_id,
    organization_id: prev.organization_id,
    input: prev.input,
    decision: {
      action,
      tool_args: toolArgs,
      reason,
      confidence
    }
  }
}];

// WF-04 | Stage 7 - Decision & Plan Validation
const item = $input.first().json;
const decision = item.decision || {};
const ALLOWED_ACTIONS = ['exchange_rate', 'weather', 'no_action'];

if (!ALLOWED_ACTIONS.includes(decision.action)) {
  throw new Error(`Invalid agent action: '${decision.action}'. Only allowlisted actions are permitted.`);
}

if (typeof decision.confidence !== 'number' || decision.confidence < 0 || decision.confidence > 1) {
  decision.confidence = 0.9;
}

return [{
  json: {
    ...item,
    action: decision.action,
    tool_args: decision.tool_args || {},
    reason: decision.reason || 'Decision reached by Agentic AI Planner.',
    confidence: decision.confidence,
    isExternalTool: decision.action !== 'no_action'
  }
}];

// WF-04 | Stage 9 - Tool Guard & URL Allowlist
const item = $input.first().json;
const action = item.action;
const args = item.tool_args || {};

let safeUrl = '';
let toolName = action;

if (action === 'exchange_rate') {
  const from = String(args.from || 'USD').toUpperCase().replace(/[^A-Z]/g, '').slice(0, 3) || 'USD';
  const to = String(args.to || 'EUR').toUpperCase().replace(/[^A-Z]/g, '').slice(0, 3) || 'EUR';
  safeUrl = `https://open.er-api.com/v6/latest/${from}`;
  item.sanitized_args = { from, to };
} else if (action === 'weather') {
  let lat = Number(args.latitude);
  let lon = Number(args.longitude);
  if (isNaN(lat) || lat < -90 || lat > 90) lat = 16.0544;
  if (isNaN(lon) || lon < -180 || lon > 180) lon = 108.2022;
  safeUrl = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current_weather=true`;
  item.sanitized_args = { latitude: lat, longitude: lon, location: args.location || 'Unknown' };
} else {
  throw new Error(`Tool guard violation: Tool '${action}' is not in the allowlist.`);
}

return [{
  json: {
    ...item,
    safe_url: safeUrl,
    tool_executed: toolName
  }
}];

// WF-04 | Stage 11 - Transformation
const isExternal = $('07 Decision & Plan').first().json.isExternalTool;
let baseInfo = {};
let apiResult = null;
let toolExecuted = 'none';

if (isExternal) {
  baseInfo = $('09 Tool Guard & URL Allowlist').first().json;
  apiResult = $input.first().json;
  toolExecuted = baseInfo.tool_executed;

  if (toolExecuted === 'exchange_rate') {
    const to = baseInfo.sanitized_args?.to || 'EUR';
    const rate = apiResult?.rates ? apiResult.rates[to] : null;
    apiResult = {
      base: baseInfo.sanitized_args?.from,
      target: to,
      rate: rate,
      last_updated: apiResult?.time_last_update_utc || new Date().toISOString()
    };
  } else if (toolExecuted === 'weather') {
    apiResult = {
      location: baseInfo.sanitized_args?.location,
      latitude: baseInfo.sanitized_args?.latitude,
      longitude: baseInfo.sanitized_args?.longitude,
      current_weather: apiResult?.current_weather || {}
    };
  }
} else {
  baseInfo = $('07 Decision & Plan').first().json;
  toolExecuted = 'none';
  apiResult = { note: 'No external API call needed. Processed purely from available context.' };
}

const finalOutput = {
  workflow_run_id: baseInfo.workflow_run_id,
  correlation_id: baseInfo.correlation_id,
  action: baseInfo.action,
  reason: baseInfo.reason,
  confidence: baseInfo.confidence,
  tool_executed: toolExecuted,
  tool_result: apiResult,
  completed_at: new Date().toISOString()
};

return [{
  json: finalOutput
}];

// WF-04 | Stage 13 - Success Log
const runInfo = $input.first().json;
const data = $('11 Transformation').first().json;

return [{
  json: {
    status: 'success',
    data: {
      action: data.action,
      reason: data.reason,
      confidence: data.confidence,
      tool_executed: data.tool_executed,
      tool_result: data.tool_result,
      workflow_run_id: data.workflow_run_id,
      correlation_id: data.correlation_id,
      db_status: runInfo.status,
      completed_at: runInfo.finished_at || data.completed_at
    }
  }
}];

// WF-04 | Stage 16 - Error Handle & Retry
const err = $input.first().json?.execution?.error || {};
const failedNode = $input.first().json?.execution?.lastNodeExecuted || 'unknown';

let workflowRunId = null;
let correlationId = null;

try {
  workflowRunId = $('05 Create Workflow Run').first()?.json?.id || null;
} catch (e) {}

try {
  correlationId = $('02 Validation').first()?.json?.correlation_id || null;
} catch (e) {}

const normalizedError = {
  message: err.message || 'Unknown workflow execution failure',
  stack: err.stack,
  failedNode,
  timestamp: new Date().toISOString(),
  retryable: ['10 Execute External API', '05 Create Workflow Run', '12 PostgreSQL Update'].includes(failedNode)
};

return [{
  json: {
    workflowRunId,
    correlationId,
    error: normalizedError
  }
}];
